#include "AddMaterialDialog.hpp"
#include "ui_AddMaterialDialog.h" // file generated by the MOC

#include <string>
#include <print>


AddMaterialDialog::AddMaterialDialog(QWidget* parent)
: QDialog(parent)
, m_impl(new Ui::AddMaterialDialog) // class denefinition generated by the MOC
{
  m_impl->setupUi(this);

  m_doubleValidator.setBottom(0.0);

  for (int i = 1; i < 10; ++i)
  {
    auto* layoutItem = m_impl->materialFormLayout->itemAt(i, QFormLayout::ItemRole::FieldRole);
    auto* widget = layoutItem->widget();
    auto* lineEdit = qobject_cast<QLineEdit*>(widget);

    if (!lineEdit)
    {
      std::println(stderr, "This line edit is ass.");
    }

    lineEdit->setValidator(&m_doubleValidator);
  }

  connect(m_impl->importMaterialButton, &QPushButton::clicked, this, &AddMaterialDialog::onImportMaterialButtonClicked);
}


AddMaterialDialog::~AddMaterialDialog()
{
  delete m_impl;
}


void AddMaterialDialog::accept()
{
  // TODO: MAKE WORK!!!!
  m_material.description = m_impl->nameLineEdit->text().toStdString();
  m_material.absorptionCoefficient = std::stod(m_impl->absorptionCoefficientLineEdit->text().toStdString());
  m_material.thermalExpansionCoefficient = std::stod(m_impl->thermalExpansionCoefficientLineEdit->text().toStdString());
  m_material.thermoOpticCoefficent = std::stod("0.0");
  m_material.thermalConductivity = std::stod("0.0");
  m_material.specificHeatCapacity = std::stod("0.0");
  m_material.refractiveIndex = std::stod("0.0");        
  m_material.youngsModulus = std::stod("0.0");
  m_material.poissonRatio = std::stod("0.0");
  m_material.mechanicalLoss = std::stod("0.0");

  QDialog::accept();

  std::println("Name: {}", m_material.description);
}


void AddMaterialDialog::onImportMaterialButtonClicked()
{
  std::println("So, I herd u like importing materials :>");
}
